int *p = malloc(sizeof *p);
*p = 10;
free(p);        // p is now dangling
*p = 20;        // use-after-free: undefined behavior

free(p);
p = NULL;       // defensive: later checks and double free are safe

int *f(void) {
  int x = 5;
  return &x;        // x dies at return
}

int *p;
{ int a = 10; p = &a; }   // a out of scope
printf("%d", *p);         // undefined
